const input = $input.first().json.body ?? $input.first().json;
const invoice = input.invoice;
if (!input.delivery_id || !input.correlation_id || !invoice?.invoice_id || typeof invoice.amount !== 'number' || invoice.amount <= 0 || !invoice.currency || !input.actor) throw new Error('Invalid invoice approval');
return [{ json: { delivery_id: input.delivery_id, correlation_id: input.correlation_id, invoice, actor: input.actor, decision: input.decision, idempotency_prefix: `invoice:${invoice.invoice_id}:${input.delivery_id}` } }];
